import{_ as t,o as i,c as e,a5 as s}from"./chunks/framework.a5no_H3L.js";const b=JSON.parse('{"title":"安全配置","description":"RabbitMQ 的安全配置涉及资源隔离、访问授权、身份认证和网络传输保护。vhost 划分资源空间，用户权限限制可执行的操作，认证机制验证客户端身份，TLS 保护连接并提供证书验证能力。本章分别说明这些配置的作用、边界和常见误区。","frontmatter":{},"headers":[],"relativePath":"rabbitmq/08-operations/chapter-02-security.md","filePath":"rabbitmq/08-operations/chapter-02-security.md"}'),r={name:"rabbitmq/08-operations/chapter-02-security.md"};function c(d,a,n,l,p,o){return i(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="安全配置" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/08-operations/chapter-02-security.md">安全配置 <a class="header-anchor" href="#安全配置" aria-label="Permalink to &quot;安全配置&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/08-operations/chapter-02-security.md"><p data-src-line="3" data-src-file="rabbitmq/08-operations/chapter-02-security.md">RabbitMQ 的安全配置涉及资源隔离、访问授权、身份认证和网络传输保护。vhost 划分资源空间，用户权限限制可执行的操作，认证机制验证客户端身份，TLS 保护连接并提供证书验证能力。本章分别说明这些配置的作用、边界和常见误区。</p></blockquote><h2 id="_1-第一层-vhost-隔离" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/08-operations/chapter-02-security.md">1. 第一层 vhost 隔离 <a class="header-anchor" href="#_1-第一层-vhost-隔离" aria-label="Permalink to &quot;1. 第一层 vhost 隔离&quot;">​</a></h2><p data-src-line="7" data-src-file="rabbitmq/08-operations/chapter-02-security.md">vhost 是 RabbitMQ 的逻辑资源隔离单位。每个 vhost 有独立的 exchange、queue、binding 和资源权限，同名资源在不同 vhost 中属于不同对象。用户只有获得目标 vhost 的访问权限，才能在其中操作资源。</p><p data-src-line="9" data-src-file="rabbitmq/08-operations/chapter-02-security.md">它的价值不在「多一套命名空间」，而在故障隔离。两个业务共用一个 <code>/</code> vhost 时，一个业务误删 exchange 会连累另一个业务，一个业务的队列堆积会增加整个 vhost 监控指标的归属和分析难度。按业务或环境拆 vhost（<code>/order</code>、<code>/payment</code>、<code>/test</code>），把互不相关的流量隔开。</p><p data-src-line="11" data-src-file="rabbitmq/08-operations/chapter-02-security.md">但 vhost 不提供物理隔离。不同 vhost 仍可能争用同一节点的 CPU、内存、磁盘和网络资源，应用也可以同时连接多个 vhost 再转发消息。RabbitMQ 支持对单个 vhost 配置部分资源限制，但这与物理隔离是两回事，业务需要独立资源容量或故障域时应评估独立集群。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add_vhost</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /order</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set_permissions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /order</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orderapp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.*&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.*&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.*&quot;</span></span></code></pre></div><p data-src-line="18" data-src-file="rabbitmq/08-operations/chapter-02-security.md">创建 vhost 后必须单独授权，用户不会自动获得新 vhost 的权限。漏掉这一步，客户端表现为 <code>access refused</code>。</p><h2 id="_2-第二层-用户与权限" tabindex="-1" data-src-line="20" data-src-file="rabbitmq/08-operations/chapter-02-security.md">2. 第二层 用户与权限 <a class="header-anchor" href="#_2-第二层-用户与权限" aria-label="Permalink to &quot;2. 第二层 用户与权限&quot;">​</a></h2><p data-src-line="22" data-src-file="rabbitmq/08-operations/chapter-02-security.md">vhost 决定用户可以进入哪些资源空间，资源权限决定用户进入后能对哪些队列和交换机执行什么操作。两层授权分别检查，获得 vhost 访问权限不等于自动获得其中所有资源的操作权限。</p><p data-src-line="24" data-src-file="rabbitmq/08-operations/chapter-02-security.md">每个 vhost 内，权限进一步拆成三项。权限检查针对具体协议操作及其涉及的资源，不是简单地按「创建、发送、接收」三类业务动作划分。</p><table tabindex="0"><thead data-src-line="26" data-src-file="rabbitmq/08-operations/chapter-02-security.md"><tr data-src-line="26" data-src-file="rabbitmq/08-operations/chapter-02-security.md"><th style="text-align:left;">权限</th><th style="text-align:left;">主要控制的操作</th></tr></thead><tbody data-src-line="28" data-src-file="rabbitmq/08-operations/chapter-02-security.md"><tr data-src-line="28" data-src-file="rabbitmq/08-operations/chapter-02-security.md"><td style="text-align:left;">configure</td><td style="text-align:left;">创建、删除队列或交换机，以及修改资源定义或行为；具体操作所需权限取决于协议操作</td></tr><tr data-src-line="29" data-src-file="rabbitmq/08-operations/chapter-02-security.md"><td style="text-align:left;">write</td><td style="text-align:left;">向资源写入消息，部分绑定操作检查目标资源的 write 权限</td></tr><tr data-src-line="30" data-src-file="rabbitmq/08-operations/chapter-02-security.md"><td style="text-align:left;">read</td><td style="text-align:left;">从资源读取消息，部分绑定操作检查源资源的 read 权限</td></tr></tbody></table><p data-src-line="32" data-src-file="rabbitmq/08-operations/chapter-02-security.md">以 AMQP 0-9-1 的 <code>queue.bind</code> 为例，RabbitMQ 检查目标队列的 write 权限和源 exchange 的 read 权限，而不是 configure 权限。</p><p data-src-line="34" data-src-file="rabbitmq/08-operations/chapter-02-security.md">三项权限独立，一个用户可以只有 write 没有 read，也就是只能发不能收，这是常见的最小权限配置。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add_user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> appuser</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app_password</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set_permissions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> appuser</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;^order\\..*&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;^order\\..*&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;^order\\..*&quot;</span></span></code></pre></div><p data-src-line="41" data-src-file="rabbitmq/08-operations/chapter-02-security.md">这个示例只是按 <code>order.</code> 命名约定演示，三个正则相同会让该用户对匹配范围内的资源同时拥有三类权限，不是所有应用账号都应照抄的模板。只发布不消费的账号应当收紧 configure 和 read，只放开 write。</p><h2 id="_3-权限正则的坑" tabindex="-1" data-src-line="43" data-src-file="rabbitmq/08-operations/chapter-02-security.md">3. 权限正则的坑 <a class="header-anchor" href="#_3-权限正则的坑" aria-label="Permalink to &quot;3. 权限正则的坑&quot;">​</a></h2><p data-src-line="45" data-src-file="rabbitmq/08-operations/chapter-02-security.md">权限用正则匹配资源名，三个正则分别作用于 configure、write、read。RabbitMQ 使用正则表达式匹配资源名，不会自动在表达式两端添加 <code>^</code> 和 <code>$</code>。正则没有锚点时，可以匹配资源名中的一部分；要限定资源名的开头、结尾或完整内容，应显式添加锚点。坑在下面三处。</p><p data-src-line="47" data-src-file="rabbitmq/08-operations/chapter-02-security.md">坑一。<code>.</code> 没转义。正则里的 <code>.</code> 匹配任意字符。想匹配 <code>order.</code> 开头的资源，应写 <code>^order\\..*</code>；若写成 <code>^order..*</code>（第二个点未转义），则 <code>orderXqueue</code> 也会被匹配，因为 <code>.</code> 匹配了 <code>X</code> 而不是字面点，权限范围比预期大。</p><p data-src-line="49" data-src-file="rabbitmq/08-operations/chapter-02-security.md">坑二。<code>.*</code> 过于宽。<code>^order\\..*</code> 只要求资源名以 <code>order.</code> 开头，不限定后续层级，所以 <code>order.admin.secret</code> 也会匹配。如果敏感资源也用了 <code>order.</code> 前缀命名，普通应用账号可能获得超出预期的访问权限。应根据资源用途划分命名空间，为不同应用配置各自的权限正则，不能只依赖共享前缀做权限隔离。</p><p data-src-line="51" data-src-file="rabbitmq/08-operations/chapter-02-security.md">坑三。空权限。三个正则里任何一个写成 <code>&quot;&quot;</code> 空串，等价于 <code>^$</code>，只匹配空字符串。常见的队列和交换机名都不是空字符串，所以它实际上关闭了该用户在这项权限上的能力。这不是 bug，是有意的收紧手段，但排查权限问题时容易被当成无效配置。</p><h2 id="_4-第三层-认证机制选型" tabindex="-1" data-src-line="53" data-src-file="rabbitmq/08-operations/chapter-02-security.md">4. 第三层 认证机制选型 <a class="header-anchor" href="#_4-第三层-认证机制选型" aria-label="Permalink to &quot;4. 第三层 认证机制选型&quot;">​</a></h2><p data-src-line="55" data-src-file="rabbitmq/08-operations/chapter-02-security.md">RabbitMQ 的认证机制和认证后端要分开理解。认证机制决定客户端以什么方式提交身份凭据，认证后端负责验证身份并参与授权决策。EXTERNAL 是一种 SASL 认证机制，LDAP 是认证与授权后端，两者不是同一层级的选项。</p><p data-src-line="57" data-src-file="rabbitmq/08-operations/chapter-02-security.md">PLAIN 就是用户名密码，默认启用的常用机制。使用默认内部后端时，凭据由 RabbitMQ 管理，也可以配置 LDAP、HTTP 等外部后端。生产环境应使用独立账号、强凭据和轮换机制，并通过 TLS 保护传输。</p><p data-src-line="59" data-src-file="rabbitmq/08-operations/chapter-02-security.md">EXTERNAL 常用于基于 TLS 客户端证书的认证，需要启用相应插件并配置客户端使用 EXTERNAL 机制。证书校验成功不等于已经完成 RabbitMQ 用户身份映射和授权。</p><p data-src-line="61" data-src-file="rabbitmq/08-operations/chapter-02-security.md">OAuth 2.0 / JWT 通过 access token 认证和授权，适合已有身份提供方和 token 签发机制的环境，但要额外配置插件、签名验证和授权规则。</p><p data-src-line="63" data-src-file="rabbitmq/08-operations/chapter-02-security.md">选型看现有基础设施和要解决的身份管理问题，不是越安全越好。已有统一 LDAP 可以用它做认证后端；微服务已有 token 体系可以评估 OAuth 2.0，但要先确认身份提供方、客户端支持和授权规则是否就绪。PLAIN 配合 TLS、强凭据和轮换机制同样能用于生产，并非只是没有其他基础设施时的临时方案。证书认证需要管理签发、分发、续期、撤销和故障恢复，没有自动续期和到期告警时，证书过期可能导致客户端连接失败或集中断连。</p><h2 id="_5-tls-加密传输" tabindex="-1" data-src-line="65" data-src-file="rabbitmq/08-operations/chapter-02-security.md">5. TLS 加密传输 <a class="header-anchor" href="#_5-tls-加密传输" aria-label="Permalink to &quot;5. TLS 加密传输&quot;">​</a></h2><p data-src-line="67" data-src-file="rabbitmq/08-operations/chapter-02-security.md">下面是 RabbitMQ 服务端要求客户端出示证书的 mTLS 配置片段。</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">listeners.ssl.default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 5671</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ssl_options.cacertfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = /path/to/ca_certificate.pem</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ssl_options.certfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = /path/to/server_certificate.pem</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ssl_options.keyfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = /path/to/server_key.pem</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ssl_options.verify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = verify_peer</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ssl_options.fail_if_no_peer_cert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = true</span></span></code></pre></div><p data-src-line="78" data-src-file="rabbitmq/08-operations/chapter-02-security.md"><code>verify_peer</code> 要求 RabbitMQ 校验客户端证书，<code>fail_if_no_peer_cert = true</code> 要求客户端必须提供证书。两者配合让 RabbitMQ 验证客户端证书，并拒绝不提供证书的客户端。严格来说，完整的双向 TLS（mTLS）还要求客户端验证服务器证书，服务端单侧配置不构成完整的 mTLS，也不等于已启用 EXTERNAL 用户认证。要直接用客户端证书作为 RabbitMQ 身份凭据，还需要启用认证插件、配置 EXTERNAL 机制，并完成证书身份到 RabbitMQ 用户的映射。</p><p data-src-line="80" data-src-file="rabbitmq/08-operations/chapter-02-security.md">如果只需要加密传输、不要求客户端出示证书，把 <code>verify</code> 设为 <code>verify_none</code>，并去掉 <code>fail_if_no_peer_cert = true</code>，两个选项要一起调整，不能只改一个。此时连接已加密，但 RabbitMQ 不验证客户端身份，客户端仍需通过其他方式认证。生产环境还要确保客户端验证服务器证书及主机名，否则只加密却无法确认连接的服务器身份。</p><h2 id="_6-网络安全" tabindex="-1" data-src-line="82" data-src-file="rabbitmq/08-operations/chapter-02-security.md">6. 网络安全 <a class="header-anchor" href="#_6-网络安全" aria-label="Permalink to &quot;6. 网络安全&quot;">​</a></h2><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">listeners.tcp.local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 127.0.0.1:5672</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">loopback_users.guest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">management.tcp.port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 15672</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">management.tcp.ip</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 127.0.0.1</span></span></code></pre></div><p data-src-line="91" data-src-file="rabbitmq/08-operations/chapter-02-security.md">Management 插件默认使用 15672 端口提供 HTTP 管理接口，默认监听所有可用网络接口，不能当作访问控制措施。上面的 <code>management.tcp.ip = 127.0.0.1</code> 是显式配置，把监听地址限制到本机。生产环境还应配合防火墙、安全组或受控反向代理限制访问来源，需要远程管理时通过 VPN 或受控代理入口访问，不把管理界面不加限制地暴露到公网。</p><p data-src-line="93" data-src-file="rabbitmq/08-operations/chapter-02-security.md"><code>loopback_users.guest = true</code> 是默认行为，guest 只能从本机回环接口连接，它只是额外保护，不能代替删除默认账号。生产环境应优先删除 guest，并为应用创建独立凭据。</p><h2 id="_7-检查清单" tabindex="-1" data-src-line="95" data-src-file="rabbitmq/08-operations/chapter-02-security.md">7. 检查清单 <a class="header-anchor" href="#_7-检查清单" aria-label="Permalink to &quot;7. 检查清单&quot;">​</a></h2><ul data-src-line="97" data-src-file="rabbitmq/08-operations/chapter-02-security.md"><li data-src-line="97" data-src-file="rabbitmq/08-operations/chapter-02-security.md">按业务拆 vhost，别让所有流量挤在 <code>/</code></li><li data-src-line="98" data-src-file="rabbitmq/08-operations/chapter-02-security.md">应用用户最小权限，能只 write 就不给 read</li><li data-src-line="99" data-src-file="rabbitmq/08-operations/chapter-02-security.md">核对 configure、write、read 三个正则是否符合实际资源命名，确认应用不具备不必要的拓扑管理权限</li><li data-src-line="100" data-src-file="rabbitmq/08-operations/chapter-02-security.md">删掉默认 guest，或至少确认 <code>loopback_users.guest</code> 生效</li><li data-src-line="101" data-src-file="rabbitmq/08-operations/chapter-02-security.md">生产启用 TLS，明确只要加密还是要加密加验证客户端</li><li data-src-line="102" data-src-file="rabbitmq/08-operations/chapter-02-security.md">确认生产客户端会验证服务器证书及主机名；采用客户端证书认证时，还要验证证书身份映射和续期流程</li><li data-src-line="103" data-src-file="rabbitmq/08-operations/chapter-02-security.md">限制管理接口的网络可达范围</li><li data-src-line="104" data-src-file="rabbitmq/08-operations/chapter-02-security.md">密码有轮换机制</li></ul>`,38)])])}const k=t(r,[["render",c]]);export{b as __pageData,k as default};
